import{_ as s,l as i,o as e,c as o,v as t,p as n,x as r,d,i as p,S as E}from"./chunks/framework.InCnrqk-.js";const C=JSON.parse('{"title":"物化视图刷新","description":"","frontmatter":{"title":"物化视图刷新","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/mv-refresh.md","filePath":"cs/mv-refresh.md","lastUpdated":1789023840000}'),c={name:"cs/mv-refresh.md"};function h(A,a,m,_,u,B){const l=i("Mermaid");return e(),o("div",null,[a[1]||(a[1]=t('<h1 id="物化视图刷新" tabindex="-1">物化视图刷新 <a class="header-anchor" href="#物化视图刷新" aria-label="Permalink to &quot;物化视图刷新&quot;">​</a></h1><div class="epigraph"><p>物化视图是带定义查询的副本；刷新把基表增量翻译成副本增量，否则读到的是过期快照。</p><footer>—— 据 Gupta and Mumick 物化视图维护；Blakeley et al.；主干视图课的维护补全</footer></div><p><a href="/cs/index-selection">上一课</a>把索引当访问路径。本课不枚举 INCLUDE 列。缺口是另一类物理设计：主干 <a href="/cs/views-materialize">视图与物化</a> 已区分虚实，并点名增量维护；进阶要把<strong>刷新时机与正确性</strong>写清，优化器才能把视图匹配当合法改写。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>基表插入 \\(\\Delta R\\)。若视图是 \\(R \\bowtie S\\)，增量大致 \\(\\Delta R \\bowtie S\\) 再并入副本（删除对称）。聚合视图要按组维护计数与合计，组计数到零则删行。缺口是：立即刷新（语句内，只读看见新结果）vs 延迟（提交后或按需）vs 全量重建。立即与事务隔离绑定；延迟则读者要接受陈旧或锁住刷新。</p><p>不可增量的定义（非单调、某些外连接、窗口）只能重建。优化器匹配：当前查询是否可被某视图覆盖（含补偿谓词）。匹配失败则当虚视图展开。</p><p><span class="marginnote">Gupta and Mumick 的维护综述。Blakeley, Larson, Tompa 对增量。本课不把每个代数算子的 delta 规则默写完，只锁定：维护必须与定义树同指称。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>增量：维护计划本身也是查询，走同一执行引擎。日志：有的系统从 WAL 解码基表变化当 \\(\\Delta\\)（与后课 CDC 同源）。刷新失败必须让副本标为不可用或回滚语句，不能 silently 旧。</p><p>并发：刷新与读者。MVCC 下可建新版本副本再切；锁模型下可能阻塞。这是事务课的接口，本课点名。</p>',10)),(e(),n(E,null,{default:r(()=>[p(l,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20BASE%5B%22%E5%9F%BA%E8%A1%A8%20delta%22%5D%20--%3E%20RULE%5B%22%E5%A2%9E%E9%87%8F%E8%A7%84%E5%88%99%22%5D%0A%20%20RULE%20--%3E%20MV%5B%22%E6%9B%B4%E6%96%B0%E5%89%AF%E6%9C%AC%22%5D%0A%20%20Q%5B%22%E7%94%A8%E6%88%B7%E6%9F%A5%E8%AF%A2%22%5D%20--%3E%20MATCH%5B%22%E8%A7%86%E5%9B%BE%E5%8C%B9%E9%85%8D%22%5D%0A%20%20MATCH%20--%3E%20SCAN%5B%22%E6%89%AB%E7%89%A9%E5%8C%96%22%5D%0A%20%20MATCH%20--%3E%20EXP%5B%22%E5%B1%95%E5%BC%80%E5%AE%9A%E4%B9%89%E6%A0%91%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>计数算法：聚合组要存支撑行数，否则不知道 <code>SUM</code> 在删行后是否删组。外连接增量更难：补 NULL 行的出现与消失。优化器代价：扫物化 vs 扫基表，用校准过的模型比。过期统计会让匹配选错。</p><p>反规范化课把无定义的宽表当危险；物化视图是有定义的宽表。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲计划提示。也不把流式物化（连续查询）写完——分析与流单元。立方体 OLAP 后课再叠维度。</p><p>后课默认：物化有刷新合同；匹配是改写不是提示。计划提示与稳定性下一课：人何时插手冻结计划。</p><p>刷新频率是陈旧预算，不是「越实时越正确」的免费午餐。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>增量刷新把基表 delta 译成视图 delta；不能增量则重建。</li><li>立即 vs 延迟绑定隔离与陈旧。</li><li>计划提示与稳定性下一课：缓存与自动换计划的运维轴。</li><li>出处：Gupta and Mumick；Blakeley et al.；Ramakrishnan and Gehrke。</li></ul>',9))])}const T=s(c,[["render",h]]);export{C as __pageData,T as default};
